try {
assert.deepEqual(JSON.parse(readFileSync('shared-state.json','utf8')),{exposed:false,retained:['real-record']});
if(existsSync('.pr-state'))assert.fail('PR draft state changed');
} catch(error) {console.error(error);process.exit(error.code==='ERR_ASSERTION'?10:2);}
